package com.aicommerce.platform.delivery.application.port;
import java.util.*; import com.aicommerce.platform.delivery.domain.PlatformObservedState;
public record WriteSucceeded(Optional<String> externalId,Optional<String> safeProviderTraceId,Optional<PlatformObservedState> observedState,NormalizedPlatformEvidence evidence) implements PlatformWriteOutcome{public WriteSucceeded{externalId=PlatformContractSupport.opt(externalId);safeProviderTraceId=PlatformContractSupport.opt(safeProviderTraceId);observedState=PlatformContractSupport.opt(observedState);PlatformContractSupport.req(evidence);externalId.ifPresent(PlatformContractSupport::safe);safeProviderTraceId.ifPresent(PlatformContractSupport::safe);if(evidence.attemptKind()!=com.aicommerce.platform.delivery.domain.PlatformAttemptKind.SUBMIT||evidence.resultKind()!=com.aicommerce.platform.delivery.domain.PlatformEvidenceResultKind.SUCCEEDED||!evidence.observedState().equals(observedState))throw PlatformContractSupport.invalid();}}
